def check(output, ctx):
    try:
        import re
        c = parse_call(output)
        if not c: return True
        req = ctx['request'].lower()
        years = set(re.findall(r'(?<!\d)(1[89]\d\d|20\d\d)(?!\d)', req))
        if not years or re.search(r'\b(last|next|this|ago|previous|since)\b', req): return True
        for k, v in (c.get('arguments') or {}).items():
            if 'year' in k.lower() and isinstance(v, (int, float)) and not isinstance(v, bool):
                if float(v).is_integer() and 1800 <= v <= 2099 and str(int(v)) not in years:
                    return False
        return True
    except Exception:
        return True

def check(output, ctx):
    try:
        import re
        c = parse_call(output)
        if not c: return True
        rd = re.sub(r'\D', '', ctx['request'])
        for v in (c.get('arguments') or {}).values():
            if isinstance(v, str):
                for d in re.findall(r'\d[\d\s\-().]{4,}\d', v):
                    dd = re.sub(r'\D', '', d)
                    if len(dd) >= 5 and dd not in rd: return False
        return True
    except Exception:
        return True

def check(output, ctx):
    try:
        import re
        c = parse_call(output)
        if not c: return True
        req = ctx['request'].lower()
        if re.search(r'\d\s*k\b|million|thousand|billion|lakh|crore|hundred', req): return True
        nums = set()
        for m in re.findall(r'\d[\d,]*\.?\d*', req):
            try: nums.add(float(m.replace(',', '')))
            except: pass
        for v in (c.get('arguments') or {}).values():
            if isinstance(v, (int, float)) and not isinstance(v, bool) and abs(v) >= 10000:
                if float(v) not in nums: return False
        return True
    except Exception:
        return True

def check(output, ctx):
    try:
        import re
        c = parse_call(output)
        if not c: return True
        req = ctx['request']
        if re.search(r'\d{4}-\d{2}-\d{2}', req): return True
        fn = next((f for f in ctx['functions'] if f.get('name') == c.get('name')), None)
        if not fn: return True
        props = fn.get('parameters', {}).get('properties', {})
        for k, v in (c.get('arguments') or {}).items():
            if isinstance(v, str) and re.fullmatch(r'\s*\d{4}-\d{2}-\d{2}\s*', v):
                d = str(props.get(k, {}).get('description', '')).lower()
                if 'yyyy' in d or 'iso' in d or 'format' in d: continue
                if re.search(r'\b(jan|feb|mar|apr|may|jun|jul|aug|sep|oct|nov|dec)[a-z]*\b', req.lower()) and re.search(r'\d', req):
                    return False
        return True
    except Exception:
        return True

