                return False
        return True
    except Exception:
        return True

def check(output, ctx):
    try:
        import re
        c = parse_call(output)
        if not c: return True
        req = ctx['request'].lower()
        rts = re.findall(r'(\d{1,2}):(\d{2})', req)
        if not rts: return True
        rset = set((int(h) % 12, m) for h, m in rts)
        for v in (c.get('arguments') or {}).values():
            if isinstance(v, str):
                for h, m in re.findall(r'(\d{1,2}):(\d{2})', v):
                    if (int(h) % 12, m) not in rset: return False
        return True
    except Exception:
        return True

