def check(output, ctx):
    try:
        import re
        c = parse_call(output)
        if not c: return True
        req = ctx['request'].lower()
        for k, v in (c.get('arguments') or {}).items():
            if not isinstance(v, str): continue
            ws = re.findall(r'[A-Za-z]+', v)
            if 1 <= len(ws) <= 5 and all(w[0].isupper() and w[1:].islower() for w in ws if len(w) > 1) and len(''.join(ws)) > 6:
                if k.lower() in ('author', 'title', 'name', 'location', 'city', 'recipient', 'director'):
                    if not any(w.lower() in req for w in ws if len(w) > 2): return False
        return True
    except Exception:
        return True

