        return True

def check(output, ctx):
    try:
        import re
        names = re.findall(r'"name"\s*:\s*"([^"]+)"', output)
        fnames = set(f.get('name') for f in ctx['functions'])
        called = [n for n in names if n in fnames]
        return len(set(called)) <= 1
    except Exception:
        return True
